\"\"\"Minimal OpenAI Responses API client using only the standard library.

This module sends private text prompts to OpenAI's Responses API. The API
key is never hardcoded: it is read from the "'``OPENAI_API_KEY`` environment
variable so secrets stay out of source code and version control.

Example:
    from openai_client import send_prompt
    reply = send_prompt("Hello, what model are you?", model="gpt-4o-mini")
    print(reply)
"""

import json
import os
import urllib.error
import urllib.request

__all__ = ["OpenAIClient", "send_prompt", "OpenAIError"]

API_URL = "https://api.openai.com/v1/responses"
DEFAULT_MODEL = "gpt-4o-mini"


class OpenAIError(Exception):
    """Raised when the Responses API request fails."""


def _read_api_key(api_key):
    key = api_key or os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError(
            "No API key provided. Set the OPENAI_API_KEY environment variable "
            "or pass api_key=... to the client."
        )
    return key


def _extract_text(payload):
    """Pull the concatenated assistant text out of a Responses API payload."""
    parts = []
    for item in payload.get("output", []):
        for content in item.get("content", []):
            if content.get("type") == "output_text":
                parts.append(content.get("text", ""))
    return "".join(parts)


class OpenAIClient:
    """Tiny wrapper around the OpenAI Responses API."""

    def __init__(self, api_key=None, model=DEFAULT_MODEL, timeout=30):
        self.api_key = [REDACTED_SECRET]
        self.model = model
        self.timeout = timeout

    def send_prompt(self, prompt, *, model=None, timeout=None):
        """Send a single text ``prompt`` and return the model'"'s reply text.\"\"\"
        body = json.dumps(
            {
                \"model\": model or self.model,
                \"input\": prompt,
            }
        ).encode(\"utf-8\")

        request = urllib.request.Request(
            API_URL,
            data=body,
            method=\"POST\",
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
        )

        try:
            with urllib.request.urlopen(
                request, timeout=timeout if timeout is not None else self.timeout
            ) as response:
                payload = json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode(\"utf-8\", \"replace\")
            raise OpenAIError(f\"HTTP {exc.code}: {detail}\") from exc
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Network error: {exc.reason}\") from exc

        if \"error\" in payload:
            raise OpenAIError(json.dumps(payload[\"error\"]))

        return _extract_text(payload)


def send_prompt(prompt, *, api_key=None, model=DEFAULT_MODEL, timeout=30):
    \"\"\"Convenience function: send "'``prompt`` and return the reply text."""
    return OpenAIClient(api_key=[REDACTED_SECRET] model=model, timeout=timeout).send_prompt(
        prompt
    )


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        print("Usage: python openai_client.py <prompt>")
        sys.exit(1)

    print(send_prompt(" ".join(sys.argv[1:])))
